      local SWAP = 993018144
      local PARAM_MENU = 2197290544 --[[soccer_parameter_menu]]
      local n = 0
      for i = 0, 28 do
        local ok, h = funcLuaCommand(1720957768, dock, 1, i, 0)
        if ok and type(h) == "number" and h ~= 0 then
